import ipaddress

POLICY = {"or": [
    {"and": [{"ip_in": "203.0.113.0/24"}, {"device_cert": True}]},
    {"mfa": True},
]}

def allowed(rule, req):
    if "or" in rule:
        return any(allowed(r, req) for r in rule["or"])
    if "and" in rule:
        return all(allowed(r, req) for r in rule["and"])
    if "ip_in" in rule:
        return ipaddress.ip_address(req["ip"]) in ipaddress.ip_network(rule["ip_in"])
    if "device_cert" in rule:
        return req.get("device_cert", False) == rule["device_cert"]
    if "mfa" in rule:
        return req.get("mfa", False) == rule["mfa"]
    return False  # 모르는 조건은 거부

for req in [{"ip": "203.0.113.7", "device_cert": True},
            {"ip": "203.0.113.7", "device_cert": False},
            {"ip": "198.51.100.9", "mfa": True},
            {"ip": "198.51.100.9"}]:
    print("허용" if allowed(POLICY, req) else "거부")

import random

def backoff(attempt, base=0.1, cap=5.0, rng=random.Random(42)):
    return rng.uniform(0, min(cap, base * 2 ** attempt))

for a in range(7):
    print(f"시도 {a}: 상한 {min(5.0, 0.1 * 2 ** a):.1f}s, 이번 대기 {backoff(a):.3f}s")

import unittest
from ex_policy import POLICY, allowed

CASES = [
    ({"ip": "203.0.113.255", "device_cert": True}, True),
    ({"ip": "203.0.114.0", "device_cert": True}, False),
    ({"ip": "198.51.100.9", "mfa": False}, False),
]

class PolicyTest(unittest.TestCase):
    def test_cases(self):
        for req, expected in CASES:
            with self.subTest(req=req):
                self.assertIs(allowed(POLICY, req), expected)

    def test_unknown_condition_is_denied(self):
        self.assertIs(allowed({"geo": "JP"}, {"ip": "203.0.113.7"}), False)

if __name__ == "__main__":
    unittest.main(verbosity=2)
